// findPointOnBezier: false or {index, x, y, angle}
// need to revamp to do a two pass check for more efficiency
// first it should do a wide check to find the nearest lines, then do a narrow check on just those lines
function findPointOnBezier(points, mx, my, detection_distance) {

	const dst2Pt = detection_distance // max distance from mouse to point
	for (let  i = 1; i < points.length; i++) {

		// estimate curve length by using the length from anchor1 to point0, 
    // point0 to point1, and point1 to anchor2

    const p0 = points[i-1]
    const p1 = points[i]

    if(points[i].bez){

      let lenBezierSeg = dist(p0.x, p0.y, p1.x1, p1.y1)

      const dist_points = dist(p0.x, p0.y, p1.x, p1.y)
      lenBezierSeg += dist_points
      lenBezierSeg += dist(p1.x2, p1.y2, p1.x, p1.y)

      const dist_anchors = dist(p1.x1, p1.y1, p1.x2, p1.y2)
      lenBezierSeg *= 0.7
      if(dist_anchors > dist_points) lenBezierSeg *= pow(dist_anchors/dist_points, 1.5)

      // calculate number of steps to cover the curve with circles with the diameter of the check area
      const steps = min(150 * lenBezierSeg / S, int(lenBezierSeg / dst2Pt)) 
      // there's a lot of overlap, to allow for more stretched curves. 
      // also prevent really short ones from having too many points
      for (let j = 1; j <= steps; j++) {
        let t = j / steps
        let x = bezierPoint(p0.x, p1.x1, p1.x2, p1.x, t)
        let y = bezierPoint(p0.y, p1.y1, p1.y2, p1.y, t)
        // circle(x, y, dst2Pt * 2) // for debug visualization of check zone
        if (dist(x, y, mx, my) < dst2Pt) {
          const tx = bezierTangent(p0.x, p1.x1, p1.x2, p1.x, t)
          const ty = bezierTangent(p0.y, p1.y1, p1.y2, p1.y, t)
          const a = atan2(ty, tx) + PI
          return {index: i-1, x, y, a}
        }
      }
    }
    else{
      const check = pDistance(mx, my, p0.x, p0.y, p1.x, p1.y)
      if(check.distance < dst2Pt){
        return {index: i-1, x: check.x, y: check.y, a: atan2(p1.y-p0.y, p1.x-p0.x) + PI}
      } 
    } 
  }
	return false
}

function pDistance(x, y, x1, y1, x2, y2) {
  // check point, point 1, point 2 
  // from Joshua on stackoverflow.com
  var A = x - x1;
  var B = y - y1;
  var C = x2 - x1;
  var D = y2 - y1;

  var dot = A * C + B * D;
  var len_sq = C * C + D * D;
  var param = -1;
  if (len_sq != 0) //in case of 0 length line
      param = dot / len_sq;

  var xx, yy;

  if (param < 0) {
    xx = x1;
    yy = y1;
  }
  else if (param > 1) {
    xx = x2;
    yy = y2;
  }
  else {
    xx = x1 + param * C;
    yy = y1 + param * D;
  }

  var dx = x - xx;
  var dy = y - yy;
  return {distance: Math.sqrt(dx * dx + dy * dy), x:xx, y:yy}
}

function findAnchorPoint(pos, points) {
  const dst2Pt = DST2PT;
	let res = -1;

  for (const [idx, pt] of points.entries()) { 

    if (abs(pos.x - pt.x) < dst2Pt && abs(pos.y - pt.y) < dst2Pt) return [idx, 0] // make it a bit easier to see and grab control points
    if (pt.x1 && dist(pos.x, pos.y, pt.x1, pt.y1) < dst2Pt) return [idx, 1]
    if (pt.x2 && dist(pos.x, pos.y, pt.x2, pt.y2) < dst2Pt) return [idx, 2]
  }

  return res;
}

