// reset drag'n'drop state
function resetDnD() {
  dnd.status = false
  dnd.index = -1
  // dnd.press_time = 0
  dnd.bez = false
  dnd.dx = 0
  dnd.dy = 0
  // first_pass = true
}

function mouseReleased() {
  if(dnd.status === MOVE_POINT && !closed_loop && (dnd.index == 0 || dnd.index == beziers.length - 1) && 
  dist(beziers[0].x, beziers[0].y, beziers[beziers.length - 1].x, beziers[beziers.length - 1].y) < DST2PT){
    toggle_loop()
    resetDnD()
  }
  if(dnd.status > 0){
    if(dnd.status === MOVE_POINT){

      const p0 = beziers[dnd.prev_index]
      // const p1 = beziers[dnd.index]
      const p1 = (dnd.index == 0 && closed_loop) ? beziers[beziers.length-1] : beziers[dnd.index]
      const p2 = beziers[dnd.next_index]

      if(dnd.sub_index === 0){
        dnd.anchor_mag1 = dist(p2.x1, p2.y1, p1.x, p1.y)
        dnd.anchor_mag2 = dist(p1.x2, p1.y2, p1.x, p1.y)
      }
      else if(dnd.sub_index === 1){
        dnd.anchor_mag1 = dist(p1.x1, p1.y1, p0.x, p0.y)
        dnd.anchor_mag2 = dist(p0.x2, p0.y2, p0.x, p0.y)
      }
      else{
        dnd.anchor_mag1 = dist(p2.x1, p2.y1, p1.x, p1.y)
        dnd.anchor_mag2 = dist(p1.x2, p1.y2, p1.x, p1.y)
      }

      beziers_temp = JSON.parse(JSON.stringify(beziers))
      selection = {...dnd}
    }
    save_state()
    resetDnD()
  } 
  else{ 
    if(save_state_needed){
      save_state()
      save_state_needed = false
    }
    resetDnD()
    selection = {...dnd}
    refresh = true
  }
}

function mouseWheel(event) {

  if(keyIsDown(ENTER)){
    const vel = -event.delta / 20
    move_rad = constrain(move_rad + vel, 5, S/4)
    // refresh = true
    return false
  }
  else if(selection.index === -1) return false

  const i = selection.index
  const i_sub = selection.sub_index
  const prev_index = selection.prev_index
  const next_index = selection.next_index

  const p0 = beziers[prev_index]
  // let p1 = beziers[i]
  const p1 = (i == 0 && closed_loop) ? beziers[beziers.length-1] : beziers[i]
  const p2 = beziers[next_index]
  const pt1 = (i == 0 && closed_loop) ? beziers_temp[beziers.length-1] : beziers_temp[i]
  const pt2 = beziers_temp[next_index]

  const vel = event.delta / 2
  // const vel2 = vel * 100  
  let delta1 = vel / dnd.anchor_mag1
  let delta2 = vel / dnd.anchor_mag2

  const close_dist = S/10

  if(i_sub === 1){
    if(dist(p1.x1, p1.y1, p0.x, p0.y) < close_dist) delta1 *= 0.5
    p1.x1 -= (pt1.x1 - p0.x) * delta1 
    p1.y1 -= (pt1.y1 - p0.y) * delta1 
  }
  else if(i_sub === 2){
    if(dist(p1.x2, p1.y2, p1.x, p1.y) < close_dist) delta2 *= 0.5
    p1.x2 -= (pt1.x2 - p1.x) * delta2
    p1.y2 -= (pt1.y2 - p1.y) * delta2
  }
  else{

    if(dist(p2.x1, p2.y1, p1.x, p1.y) < close_dist) delta1 *= 0.5
    if(dist(p1.x2, p1.y2, p1.x, p1.y) < close_dist) delta2 *= 0.5

    p2.x1 -= (pt2.x1 - p1.x) * delta1 
    p2.y1 -= (pt2.y1 - p1.y) * delta1

    p1.x2 -= (pt1.x2 - p1.x) * delta2
    p1.y2 -= (pt1.y2 - p1.y) * delta2
  }

  refresh = true
  // blocks page scrolling, zooming, etc.
  return false
}

function save_state(){

  // prevent adding to undo history when something is selected with the mouse but no move is made.
  if(dnd.status > 0 && dnd.dx == 0 & dnd.dy == 0) return

  if(undo_index > 0){
    undo_history.splice(0,undo_index) // clears unneeded undo history
  }

  undo_history.unshift({ 
    beziers_state:JSON.stringify(beziers),
    bW:bound_box.w, bH:bound_box.h, 
    loop_state:closed_loop
  })

  if(undo_history.length > max_undo_levels) undo_history.pop()
  undo_index = 0
  // console.log('saved state')
}

function change_state(dir){
  let shifted = false
  const undo_index_temp = undo_index
  if(dir == -1 && undo_index + 1 < undo_history.length) undo_index++
  if(dir == 1 && undo_index - 1 >= 0) undo_index--
  if(undo_index !== undo_index_temp){
    shifted = true
    const U = undo_history[undo_index]
    beziers = JSON.parse(U.beziers_state)
    bound_box = {w:U.bW, h:U.bH}
    origin = {x:(W - bound_box.w) / 2, y:(H - bound_box.h) / 2}
    closed_loop = U.loop_state
  }
  if(closed_loop){
    strokeWeight(1)
    fill(fill_col) 
  } 
  else{
    strokeWeight(2)
    noFill()
  } 
  refresh = true
  return shifted
}

// draw the shape of bezier curve
function drawBezierPts(points, push_pull) {
  beginShape()
  let hue_val, selected
  const showHelper2 = keyIsDown(ENTER) || (dnd.status == MOVE_POINT && dnd.sub_index == 0 && keyIsDown(SHIFT))
  for (let i = 0; i < points.length; i++) {
    if(push_pull){
      const p = points[i]
      const d = dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), p.x, p.y)
      let move_amount = min(max_move_speed, move_rad / d)
      if(move_amount > 0.5 && d > 15){
        if(dnd.move_dir == 1) move_amount = max_move_speed * d / move_rad
        else move_amount *= 1.5
        // console.log(move_amount)
        save_state_needed = true
        const move_x = dnd.move_dir * move_amount * (p.x - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))))/d
        const move_y = dnd.move_dir * move_amount * (p.y - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))/d
        p.x += move_x
        p.y += move_y
        if(p.bez){
          p.x2 += move_x
          p.y2 += move_y
          if(i+1 < points.length){
            points[i+1].x1 += move_x
            points[i+1].y1 += move_y
          }
          else if(closed_loop){
            points[1].x1 += move_x
            points[1].y1 += move_y
          }
        }
        else if(!closed_loop && i == 0){
          points[1].x1 += move_x
          points[1].y1 += move_y
        }
      }
    }

    if(showHelper){
      selected = (selection && i === selection.index)
      hue_val = (round(i*2)/2)/points.length * 50 + (i % 2) * 50
    } 
    if(points[i].bez == false){
      vertex(points[i].x, points[i].y);
      if(showHelper) drawAnchor(points[i].x, points[i].y, dot_diam * (1 + 0.6 * (i == 0)), selected, 0, hue_val)
    }
    else{
      const p0 = points[i-1]
      const p1 = points[i]

      bezierVertex(p1.x1, p1.y1, p1.x2, p1.y2, p1.x, p1.y)

      if(showHelper || showHelper2) {
        push()

        let highlight = 0
        const h0 = drawAnchor(p1.x, p1.y, dot_diam, selected, 0, hue_val)
        if(showHelper && !showHelper2){

          const h1 = drawAnchor(p1.x1, p1.y1, dot_diam, selected, 1, hue_val)
          const h2 = drawAnchor(p1.x2, p1.y2, dot_diam, selected, 2, hue_val)

          highlight = max(h0, h1, h2)

          drawingContext.setLineDash([5 + highlight * 3])
          if(highlight){
            strokeWeight(3)
            selection.index = i
          }

          stroke(hue_val,100,100,100)
          line(p0.x, p0.y, p1.x1, p1.y1)
          line(p1.x, p1.y, p1.x2, p1.y2)
          pop()
        } 
      }
    }
  }
  endShape()
}

function drawAnchor(x, y, diam, selected, pt, hue_val) {
  const selected_pt = (selected && pt == selection.sub_index)
	push()
	let diam2 = diam
	const val = 70 + 30 * selected_pt
	if(selected_pt){
		strokeWeight(3)
		diam2 *= 1.5
	}
	if(!hue_val) hue_val = 0
	fill(hue_val,val,val,val)
  if(pt) circle(x, y, diam2)
  else square(x, y, diam2)
	pop()
	return selected_pt
}

