// convert points to bezier curves
// ----------------------------------------------------------------------------------------------------
// ----------------------------------------------------------------------------------------------------
function points2beziers(points, loop=true, init=false, adjust_all=true) {

  refresh = true
  points[0].bez = false

  if (!points || points.length <= 1) return

  if (points.length === 2 + loop) {
    const L = S/3
    if(loop){
      // 2 starting points = 3 array elements
      points[1].x1 = int(points[0].x + L)
      points[1].y1 = int(points[0].y)
      points[1].x2 = int(points[1].x + L)
      points[1].y2 = int(points[1].y)

      points[2].x1 = int(points[1].x - L)
      points[2].y1 = int(points[1].y)
      points[2].x2 = int(points[2].x - L)
      points[2].y2 = int(points[2].y)
      if(init){
        points[1].bez = true
        points[2].bez = true
      } 
    }
    else{
      // 2 point = 1 line
      points[1].x1 = int(w - L)
      points[1].y1 = int(lerp(points[0].y, points[1].y, 0.3))
      points[1].x2 = int(w + L)
      points[1].y2 = int(lerp(points[0].y, points[1].y, 0.7))
      if(init) points[1].bez = true
    }
    return
  }

  // 3 or more points
  let vz, v_prev, v_next, p1, limit, offset
  const len = points.length
  const len1 = points.length - 1


  if(adjust_all || (!loop && len == 3)){
    limit = points.length - 1
    offset = 0
    // if(first_pass) console.log(limit, len)
  }
  else{
    offset = selection.index - 2
    limit = 4
    // if(first_pass) console.log(offset, len)
    // if(loop){
    //   // console.log(offset, limit)
    // }
    // else{
    //   offset = max(selection.index - 2, 0)
    //   limit = constrain(len - (selection.index - 2), 2, 4)
    //   console.log(len, len - (selection.index), limit)
    // }
  }

  // need to set it up to work properly with both closed and open loop.

  let offset2 = 0

  for (let n = 1; n <= limit; n++) {

    let i = (n + offset + len) % len
    if(n > 1 && i == 0) offset2 = 1
    i += offset2

    // if(!loop && i == 0) continue

    let prev_index = i - 1 > 0 ? (i - 1) % len1 : (i - 1 + len1) % len1

    let prev_index2 = null
    if(adjust_all && n === 1) prev_index2 = i - 2 > 0 ? (i - 2) % len1 : (i - 2 + len1) % len1
    let next_index = (i + 1) % len1


    if(selection.index == 1 && loop && n == 1){ // hacky, but it works
      prev_index = len1-1
      i = len1
      next_index = 1
    }

    // if(first_pass){
    //   if(adjust_all && n === 1) console.log(selection.index)
    //   console.log(n, prev_index2, prev_index, i, next_index)
    // }

    const prev = points[prev_index]
    const current = points[i]
    const next = points[next_index]

    if(init) points[i].bez = true

    if (adjust_all && n === 1) {
      v_prev = createVector(
        prev.x - points[prev_index2].x,
        prev.y - points[prev_index2].y
      )
      v_next = createVector(
        prev.x - current.x,
        prev.y - current.y
      )
      angleBetw = p5.Vector.angleBetween(v_prev, v_next)
      vz = v_prev.copy().mult(0.3).rotate(angleBetw / 2 + HALF_PI * Math.sign(angleBetw))
    }

    p1 = createVector(prev.x, prev.y).sub(vz)
    p1 = { x: p1.x, y: p1.y }

    v_prev = createVector(
      current.x - prev.x,
      current.y - prev.y
    )
    v_next = createVector(
      current.x - next.x,
      current.y - next.y
    )

    angleBetw = p5.Vector.angleBetween(v_prev, v_next)
    vz = v_prev.copy().mult(0.3).rotate(angleBetw / 2 + HALF_PI * Math.sign(angleBetw))

    let p2 = createVector(current.x, current.y).add(vz);
    p2 = { x: p2.x, y: p2.y }

    if(adjust_all || (n > 1 && i > 0 &&!(!loop && selection.index > 1 && i == 1))){
      points[i].x1 = ~~p1.x
      points[i].y1 = ~~p1.y
    } 
    if(adjust_all || n < limit){
      points[i].x2 = ~~p2.x
      points[i].y2 = ~~p2.y
    }
  }
  // first_pass = false
}

// generate parameterized p5js code of the shape in the console and clipboard
function genOutput(beziers,origin_x,origin_y,array_output) {

  //origin_x and origin_y can be in range of 0-1, with 0.5 being the midline

  op = constrain(output_precision, 0, 9)

	beziers_temp = JSON.parse(JSON.stringify(beziers))

  let bezier_text = ''

  const bW = bound_box.w
  const bH = bound_box.h

  const oW = origin.x + origin_x * bW
  const oY = origin.y + origin_y * bH

	beziers_temp.forEach((e) => {
		e.x = nf((e.x - oW) / bW,0,op)
		e.y = nf((e.y - oY) / bH,0,op)
    if(e.bez){
      e.x1 = nf((e.x1 - oW) / bW,0,op)
      e.y1 = nf((e.y1 - oY) / bH,0,op)
      e.x2 = nf((e.x2 - oW) / bW,0,op)
      e.y2 = nf((e.y2 - oY) / bH,0,op)
    }
	})

  if(array_output){
    bezier_text = '['
    beziers_temp.forEach((e) => {
      if(e.bez) bezier_text += `[${e.x1}, ${e.y1}, ${e.x2}, ${e.y2}, ${e.x}, ${e.y}],\n`
      else bezier_text += `[${e.x}, ${e.y}],\n`
    })
    bezier_text = bezier_text.slice(0,-2) + ']'
  }
  else{
    bezier_text += `\n\nlet bW = ${round(bW,1)}\nlet bH = ${round(bH,1)}\n\n`
    bezier_text += `beginShape()\n`
    for (let i = 0; i < beziers_temp.length; i++) {
      const bez = beziers_temp[i]
      if(bez.bez) bezier_text += `bezierVertex(${bez.x1} * bW, ${bez.y1} * bH, ${bez.x2} * bW, ${bez.y2} * bH, ${bez.x} * bW, ${bez.y} * bH)\n`
      else bezier_text += `vertex(${bez.x} * bW, ${bez.y} * bH)\n`
    }
    bezier_text += 'endShape()'
  }

  console.log(bezier_text)
  // navigator.clipboard.writeText(bezier_text)
  copyToClipboard(bezier_text)
}

// I did not write this function, but copied it from one of Aaron Reuland's sketches, and he copied it from Greg Lowe on Stack Overflow
// even though some of the methods are deprecated, there is no alternative as of 2024, and they seem to still be supported.
function copyToClipboard(text) {
	if (window.clipboardData && window.clipboardData.setData) {
		// Internet Explorer-specific code path to prevent textarea being shown while dialog is visible.
		return window.clipboardData.setData("Text", text);

	} else if (document.queryCommandSupported && document.queryCommandSupported("copy")) {
		var textarea = document.createElement("textarea");
		textarea.textContent = text;
		textarea.style.position = "fixed"; // Prevent scrolling to bottom of page in Microsoft Edge.
		document.body.appendChild(textarea);
		textarea.select();
		try {
			return document.execCommand("copy"); // Security exception may be thrown by some browsers.
		} catch (ex) {
			console.warn("Copy to clipboard failed.", ex);
			return prompt("Copy to clipboard: Ctrl+C, Enter", text);
		} finally {
			document.body.removeChild(textarea);
		}
	}
}

